// Diálogos internos de la aplicación. Evitan alert/confirm del navegador.
let dmOpenAppDialog = null;
function appAlert(message,title="Aviso"){
  if(typeof dmOpenAppDialog!=="function"){
    console.warn(String(message||""));
    return Promise.resolve(true);
  }
  return dmOpenAppDialog({type:"alert",title,message:String(message||"")});
}
function appConfirm(message,title="Confirmar acción"){
  if(typeof dmOpenAppDialog!=="function")return Promise.resolve(false);
  return dmOpenAppDialog({type:"confirm",title,message:String(message||"")});
}

